CREATE TABLE IF NOT EXISTS billing_documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id VARCHAR(255) NOT NULL REFERENCES user_profiles(auth_subject) ON DELETE CASCADE, type VARCHAR(20) NOT NULL CHECK(type IN ('quote','invoice')), status VARCHAR(30) NOT NULL DEFAULT 'sent', document_number VARCHAR(80) NOT NULL UNIQUE, share_token VARCHAR(120) NOT NULL UNIQUE, plan_key VARCHAR(50) NOT NULL, billing_cycle VARCHAR(20) NOT NULL, customer_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb, supplier_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb, banking_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb, line_items JSONB NOT NULL DEFAULT '[]'::jsonb, subtotal_cents INTEGER NOT NULL, taxable_total_cents INTEGER NOT NULL, vat_cents INTEGER NOT NULL, total_cents INTEGER NOT NULL, issue_date TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(), validity_date TIMESTAMP WITH TIME ZONE, payment_id UUID REFERENCES billing_payments(id), notes TEXT, email_status VARCHAR(30), email_message_id VARCHAR(255), crm_status VARCHAR(30), crm_lead_id VARCHAR(255), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS billing_documents_user_idx ON billing_documents(user_id,created_at DESC);
